output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "It is forbidden to push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "no_north_from_mouth_with_cart",
    "text": "At the mouth of an upper single-file shelf aisle, it is forbidden to move north into the aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "upperSingleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "northIntoUpperSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "upperSingleFileMouth",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "northIntoUpperSingleFileWithCart"
    }
  },
  {
    "id": "park_only_at_narrow_mouth",
    "text": "Dropping or leaving a cart is permitted only at designated wide aisle mouths serving single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "designatedCartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "designatedCartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_parking",
    "text": "After parking a cart at a single-file aisle mouth, the agent is obliged to retrieve the cart from a mouth before leaving.",
    "abstraction": {
      "state_properties": {
        "designatedCartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "designatedCartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "designatedCartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "return_to_mouth_after_single_file",
    "text": "An agent who enters a single-file shelf aisle without a cart is obliged to return to the corresponding wide aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "singleFileShelfAisle",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "singleFileAisleMouth"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The agent is forbidden to leave the supermarket without the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "exitWithoutCart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exitWithoutCart"
    }
  },
  {
    "id": "one_way_no_west",
    "text": "Westbound movement is forbidden, consistent with one-way circulation through the store aisles.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "westboundMove": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westboundMove"
    }
  }
]
